"use client";

import type { ReactNode } from "react";
import { AbsoluteFill } from "remotion";
import {
  AUDIT_COLORS,
  AuditClock,
  DEMO,
  DemoDashboard,
  FONT,
  Guide,
  type GuideSpec,
  OutlineBox,
  Pill,
  Ruler,
} from "@/lib/remocn/audit-core";
import { useSceneConfig } from "@/lib/remocn/frame-rate";
import {
  type ResolvedTimeline,
  type Timing,
  useTimeline,
} from "@/lib/remocn/timeline";
import { type LayoutGuidesElementId, layoutGuidesTimeline } from "./timeline";

export type LayoutGuidesProps = {
  /** UI to lay guides over, in a 1280x720 frame. Defaults to a demo calendar dashboard. */
  children?: ReactNode;
  /** Column edges, highlight, ruler and now line, in frame pixels. */
  guides?: GuideSpec;
  color?: string;
  /** Color of the now line and its label. */
  nowColor?: string;
  background?: string;
  speed?: number;
  /**
   * Moves, trims or stretches single column guides, the highlight, the
   * ruler and the now line, by the ids in `./timeline`. Frames on the scene
   * timeline, after `speed`.
   */
  timing?: Timing<LayoutGuidesElementId>;
};

export const layoutGuidesDefaults = {
  color: AUDIT_COLORS.fix,
  nowColor: AUDIT_COLORS.scan,
  background: AUDIT_COLORS.stage,
  speed: 1,
};

export const layoutGuidesLength = 54;

export function LayoutGuides(props: LayoutGuidesProps) {
  const { speed = 1, timing } = props;
  const { durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    layoutGuidesTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  return (
    <AuditClock speed={speed}>
      <Scene {...props} tl={tl} />
    </AuditClock>
  );
}

function Scene({
  children,
  guides = children ? undefined : DEMO.after.guides,
  color = layoutGuidesDefaults.color,
  nowColor = layoutGuidesDefaults.nowColor,
  background = layoutGuidesDefaults.background,
  tl,
}: LayoutGuidesProps & { tl: ResolvedTimeline<LayoutGuidesElementId> }) {
  return (
    <AbsoluteFill style={{ background, fontFamily: FONT }}>
      {children ?? <DemoDashboard v={2} />}
      {guides && (
        <Marks guides={guides} color={color} nowColor={nowColor} tl={tl} />
      )}
    </AbsoluteFill>
  );
}

/** Column guides drop in, the highlight fills, then the now line slides across. */
function Marks({
  guides,
  color,
  nowColor,
  tl,
}: {
  guides: GuideSpec;
  color: string;
  nowColor: string;
  tl: ResolvedTimeline<LayoutGuidesElementId>;
}) {
  const { columns, top, bottom, highlight, ruler, now } = guides;
  const h = highlight?.rect;
  const lit = h && highlight ? tl.get("highlight") : undefined;
  const nowEl = now ? tl.get("now") : undefined;
  return (
    <>
      {columns.map((x, i) => (
        <Guide
          key={x}
          x={x}
          y={top}
          length={bottom - top}
          vertical
          color={color}
          dashed
          delay={tl.get(`column:${i}`).start}
        />
      ))}
      {h && highlight && lit && (
        <>
          <OutlineBox
            rect={h}
            color={color}
            fill={`${color}14`}
            inset={0}
            radius={0}
            delay={lit.start}
          />
          <OutlineBox
            rect={{ x: h.x + 6, y: h.y + 4, w: h.w - 12, h: 22 }}
            color={color}
            radius={4}
            inset={0}
            delay={lit.start + lit.beat("headerAt")}
          />
          <Pill
            x={h.x + h.w / 2}
            y={h.y + 4}
            text={highlight.label}
            color={color}
            delay={lit.start + lit.beat("labelAt")}
            anchor="above"
          />
        </>
      )}
      {ruler && (
        <Ruler
          from={ruler.from}
          to={ruler.to}
          label={ruler.label}
          color={color}
          delay={tl.get("ruler").start}
          labelSide={ruler.side}
        />
      )}
      {now && nowEl && (
        <>
          <Guide
            x={now.from}
            y={now.y}
            length={now.to - now.from}
            color={nowColor}
            width={1.5}
            delay={nowEl.start}
          />
          <Pill
            x={now.from}
            y={now.y}
            text={now.label}
            color={nowColor}
            delay={nowEl.start}
            anchor="left"
          />
        </>
      )}
    </>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The layout guides: the column edges dropping in one after another, the
// highlighted column filling, the ruler measuring, then the now line sliding
// across. Frames on the 30 fps scene timeline, after `speed`. The ids are
// public: a saved `timing` prop refers to them.

export type LayoutGuidesElementId =
  | `column:${number}`
  | "highlight"
  | "ruler"
  | "now";

export interface LayoutGuidesTimingProps {
  guides?: {
    columns: readonly number[];
    highlight?: { label: string };
    ruler?: { label: string };
    now?: { label: string };
  };
  children?: unknown;
}

/** Frame the first guide starts dropping. */
const START = 8;
/**
 * The demo dashboard's guides (`DEMO.after.guides` in audit-core): six column
 * edges, a highlight, a ruler and a now line.
 */
const DEMO_GUIDES = {
  columns: [0, 0, 0, 0, 0, 0],
  highlight: { label: "Mon 2 · today" },
  ruler: { label: "gutter" },
  now: { label: "10:15 AM" },
};

// `column:<i>` drops guide i in over its length; the guides form a chain.
// `highlight` fills the column, outlines its header from `headerAt` and pops
// its label at `labelAt`. `ruler` draws the measurement; `now` slides the
// now line across with its label.
export const layoutGuidesTimeline = defineTimeline<
  LayoutGuidesElementId,
  LayoutGuidesTimingProps
>(({ guides, children }) => {
  const spec = guides ?? (children ? undefined : DEMO_GUIDES);
  if (!spec) return [];
  const elements: TimelineElement<LayoutGuidesElementId>[] = spec.columns.map(
    (_, i) => ({
      id: `column:${i}`,
      lane: "Guides",
      label: `column ${i + 1}`,
      start: START + i * 3,
      length: 16,
      follows: i > 0 ? `column:${i - 1}` : undefined,
    }),
  );
  if (spec.highlight) {
    elements.push({
      id: "highlight",
      lane: "Highlight",
      label: spec.highlight.label,
      start: START + 14,
      length: 14,
      beats: { headerAt: 6, labelAt: 12 },
    });
  }
  if (spec.ruler) {
    elements.push({
      id: "ruler",
      lane: "Ruler",
      label: spec.ruler.label,
      start: START + 24,
      length: 12,
    });
  }
  if (spec.now) {
    elements.push({
      id: "now",
      lane: "Now",
      label: spec.now.label,
      start: START + 30,
      length: 16,
    });
  }
  return elements.sort((a, b) => a.start - b.start);
});
